/* V90.62: crash-safe old-slot replacement with one authoritative ledger marker.
   Never delete source before replacement is written. A retry may finish a pending
   reset, but must never credit again even when the balance has been spent. */
 resetRebuilt(id,n=1){
  this.check(id);this.slot(n);
  const found=this.read(id,n);
  if(!found||!found.reset)throw Error('当前不是待重置的旧存档，禁止覆盖');
  const key=this.key(id,n),backup=this.backupKey(id,n),doneKey=key+'-rebuild-compensated';
  const raw=this.readKey(found.reset.source==='自动备份'?backup:key);
  if(!raw)throw Error('无法确认旧档原始记录，操作已取消');
  const old=JSON.parse(raw);
  if(!old||typeof old!=='object'||Array.isArray(old)||!old.inv||typeof old.inv!=='object'||Array.isArray(old.inv)||
     !old.pos||!Number.isInteger(old.pos.x)||!Number.isInteger(old.pos.y)||old.pos.x<0||old.pos.x>=8||old.pos.y<0||old.pos.y>=8||
     (old.version>=14?(old.race!==id||old.character!==id):(id!=='human')))
    throw Error('旧档内容或种族身份不符，禁止重置');
  const ledger=this.legacy(id,n);
  const oldMarker=!!this.readKey(doneKey);
  const already=!!ledger.rebuildCompensation||oldMarker;
  const paid=already?0:found.reset.tier;
  const next=new Game(null,261014,id),ups=ledger.upgrades||{};
  next.s.maxHp+=4*(ups.vigor||0);next.s.hp+=4*(ups.vigor||0);
  next.s.maxSpirit+=4*(ups.spirit||0);next.s.spirit+=4*(ups.spirit||0);
  next.s.attack+=ups.attack||0;
  const nextRaw=JSON.stringify(next.state());
  /* Check the new record is readable before writing any primary or ledger. */
  new Game(JSON.parse(nextRaw),261014,id);
  /* Keep recoverable old content through all failure points. */
  if(this.readKey(key)&&!this.readKey(backup))this.storage.setItem(backup,this.readKey(key));
  if(!ledger.rebuildCompensation){
   ledger.balance+=paid;ledger.total+=paid;
   ledger.rebuildCompensation={version:1,tier:paid,source:found.reset.source,
    claimedAt:new Date().toISOString(),legacyMarker:oldMarker};
   /* Credit plus claimed marker are written as ONE localStorage record. */
   this.putLegacy(id,n,ledger);
  }
  /* A failed write leaves the original slot intact; the ledger marker
     ensures retry never repeats a payment. */
  this.storage.setItem(key,nextRaw);
  try{this.storage.setItem(doneKey,'1');}catch{}
  try{this.storage.removeItem(backup);}catch{}
  return {game:next,paid,total:ledger.rebuildCompensation.tier};
 }
